44	/** A free jailed username on the node, derived from the email + random salt. */
45	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
46	  for (let i = 0; i < 8; i++) {
47	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
48	    if (!isValidUnixUsername(name)) continue;
49	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
50	    if (!taken) return name;
51	  }
52	  throw new Error("Could not allocate a username — try again.");
53	}
