212	/** Create a scoped database for an account (within the plan's maxDatabases). */
213	export async function createHostingDatabase(accountId: string, label: string): Promise<{ error?: string; ok?: boolean; password?: string }> {
214	  const user = await requireUser();
215	  await assertNotImpersonating();
216	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { id: true, userId: true, status: true, username: true, maxDatabases: true } });
217	  if (!a) return { error: "Account not found." };
218	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
219	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
220	  // A short, safe suffix keyed off the account username: <user>_<slug>.
221	  const slug = String(label ?? "").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
222	  const name = `${a.username}_${slug}`.slice(0, 64);
223	  const dbUser = name.slice(0, 32);
224	  if (!/^[a-z0-9_]{1,64}$/.test(name)) return { error: "Invalid database name." };
225	  const password = randomBytes(12).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 20);
226	  // Count + create in ONE serializable transaction, so concurrent creates can't
227	  // both read a stale count and blow past the plan cap (audit 2026-08-01 TOCTOU).
228	  try {
229	    await db.$transaction(async (tx) => {
230	      const n = await tx.hostingDatabase.count({ where: { accountId: a.id, status: { in: ["PENDING", "ACTIVE"] } } });
231	      if (n >= a.maxDatabases) throw new Error("CAP");
232	      await tx.hostingDatabase.create({ data: { accountId: a.id, name, dbUser, passwordEnc: encryptSecret(password), status: "PENDING" } });
233	    }, { isolationLevel: "Serializable" });
234	  } catch (e) {
235	    if (e instanceof Error && e.message === "CAP") return { error: `Your plan allows ${a.maxDatabases} database${a.maxDatabases === 1 ? "" : "s"}.` };
236	    // Serialization conflict (P2034) or the unique(accountId,name) collision.
237	    return { error: "A database with that name already exists, or the request raced — try again." };
238	  }
239	  revalidatePath("/dashboard/hosting");
240	  // Shown ONCE — the encrypted copy is cleared by the provisioner after it applies it.
241	  return { ok: true, password };
242	}
