264	/** Recent panel tasks for an account (so the UI can show progress + one-time results). */
265	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
266	  const user = await requireUser();
267	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
268	  if (!a) return [];
269	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
270	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
271	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
272	  // then clear it so it isn't shown again on the next poll.
273	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
274	  const toClear = rows.filter((t) => t.status === "DONE" && t.result);
275	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
276	  return out;
277	}
