/** Write + (re)load an account's FPM pool for a given PHP version. */
async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConf(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
}

