/**
 * Plan recommendation helper (pure).
 *
 * Turns a shared-hosting plan's own specs (disk, bandwidth, sites, databases)
 * into a short, human "recommended for …" descriptor. The tier is DERIVED from
 * the specs — nothing is hard-coded per plan — so it stays correct when an admin
 * edits a plan or adds a new one. Computed at render time from existing fields;
 * no schema, no persistence.
 */

export type HostingPlanSpecs = {
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
};

export type HostingTier = "starter" | "personal" | "business" | "pro";

export type HostingRecommendation = {
  /** Machine tier, derived from the capacity score. */
  tier: HostingTier;
  /** One-line "Recommended for …" headline for a plan card. */
  headline: string;
  /** A slightly longer supporting sentence (rough traffic / use fit). */
  detail: string;
};

/**
 * A coarse capacity score from the specs. Each dimension contributes points on
 * its own scale, so a plan that is generous on ANY axis (lots of disk, many
 * sites, big bandwidth, many DBs) is pulled up a tier — the way a real buyer
 * reads a spec sheet. Deliberately simple + monotonic so tiering is predictable.
 */
export function planCapacityScore(specs: HostingPlanSpecs): number {
  const disk = Math.max(0, specs.diskGB || 0);
  const sites = Math.max(1, Math.floor(specs.maxSites || 1));
  const dbs = Math.max(0, Math.floor(specs.maxDatabases || 0));
  const bw = Math.max(0, specs.bandwidthTB || 0);

  // Disk: ~1 point per 10 GB (the dominant signal buyers anchor on).
  const diskPts = disk / 10;
  // Sites beyond the first each add weight (multi-site → business).
  const sitePts = (sites - 1) * 1.5;
  // Databases signal app-heaviness (WooCommerce, forums) — 1 point each past 1.
  const dbPts = Math.max(0, dbs - 1) * 1;
  // Bandwidth: ~1 point per TB.
  const bwPts = bw;

  return diskPts + sitePts + dbPts + bwPts;
}

/**
 * Derive the recommendation for a plan from its specs.
 *
 * Thresholds are tuned so a typical spec ladder lands sensibly:
 *   ~1 GB / 1 site / 1 db / 1 TB   → starter   (single small/one-page site)
 *   ~10 GB / 1–2 sites / 2 db      → personal  (blog / small business site)
 *   ~40 GB / 3+ sites or 3+ db     → business  (several sites, steady traffic)
 *   big disk / many sites / >5 TB  → pro       (busy store / high traffic)
 */
export function recommendHostingPlan(specs: HostingPlanSpecs): HostingRecommendation {
  const score = planCapacityScore(specs);
  const sites = Math.max(1, Math.floor(specs.maxSites || 1));
  const dbs = Math.max(0, Math.floor(specs.maxDatabases || 0));

  // Strong single signals promote a plan even if the score is mid: lots of
  // allowed sites is inherently "business", a store-grade DB count is "pro".
  const manySites = sites >= 3;
  const storeGrade = specs.bandwidthTB >= 5 || specs.diskGB >= 80 || dbs >= 6;

  if (storeGrade || score >= 12) {
    return {
      tier: "pro",
      headline: "Fits a busy WooCommerce store or high-traffic site",
      detail: "Room for an online store, a media-heavy site, or several active sites with steady daily traffic.",
    };
  }
  if (manySites || score >= 5) {
    return {
      tier: "business",
      headline: "Good for a small business site or a few projects",
      detail:
        sites >= 2
          ? `Host up to ${sites} sites — a business site plus side projects, ~5–20k visits/month.`
          : "A growing business site or content blog with ~5–20k visits/month.",
    };
  }
  if (score >= 2) {
    return {
      tier: "personal",
      headline: "Great for a personal site or blog",
      detail: "A blog, portfolio, or small business brochure site — comfortably ~1–2k visits/month.",
    };
  }
  return {
    tier: "starter",
    headline: "Ideal for a one-page or starter site",
    detail: "A single simple site — landing page, portfolio, or brochure — with up to ~100 visitors a day.",
  };
}

