test("accountPaths jails everything under the user's home", () => {
  const p = accountPaths("nxalice");
  assert.equal(p.home, "/home/nxalice");
  assert.equal(p.webroot, "/home/nxalice/public_html");
  assert.ok(p.fpmPool.endsWith("nxalice.conf"));
});

/* ------------------------------------------------------------------ *
 * Provisioner hardening — the config a shared box runs. A gap here is
 * a cross-tenant breach, so these assert the SECURITY properties, not
 * just that a string is produced.
 * ------------------------------------------------------------------ */

test("disable_functions blocks every known jail-break, incl. pcntl_exec", () => {
  const list = new Set(PHP_DISABLED_FUNCTIONS);
  // Command execution must all be present.
  for (const fn of ["exec", "passthru", "shell_exec", "system", "proc_open", "popen"]) {
    assert.ok(list.has(fn), `missing ${fn}`);
  }
  // The specific escapes the security review flagged.
  for (const fn of ["pcntl_exec", "pcntl_fork", "pcntl_signal", "putenv", "mail", "dl", "proc_nice", "symlink", "link", "error_log", "ffi"]) {
    assert.ok(list.has(fn), `missing ${fn}`);
  }
  // No duplicates, and the string form is comma-joined with no spaces.
  assert.equal(PHP_DISABLED_FUNCTIONS.length, list.size, "duplicate entries");
  assert.equal(phpDisableFunctions(), [...PHP_DISABLED_FUNCTIONS].join(","));
  assert.ok(!phpDisableFunctions().includes(" "), "no spaces in disable_functions");
});

test("account filesystem plan is not world-readable (no 755 webroot)", () => {
  const fs = accountFsPlan("nxalice");
  // Home: root-owned (chroot-safe), world-traversable but NOT the old 755.
  assert.equal(fs.home.owner, "root:root");
  assert.equal(fs.home.mode, "711");
  assert.notEqual(fs.home.mode, "755");
  // Webroot: owned by the tenant, group www-data (nginx reads via GROUP), setgid,
  // and crucially NO world bit.
  assert.equal(fs.webroot.owner, "nxalice:www-data");
  assert.equal(fs.webroot.mode, "2750");
  assert.equal(fs.nginxGroup, "www-data");
  const otherDigit = Number(fs.webroot.mode.slice(-1));
  assert.equal(otherDigit, 0, "webroot must have no world permission bits");
  // tmp: private to the tenant.
  assert.equal(fs.tmp.owner, "nxalice:nxalice");
  assert.equal(fs.tmp.mode, "700");
});

test("fpm pool: hardened limits, open_basedir scoped to home, no /tmp", () => {
  const conf = fpmPoolConfig("nxalice", "/home/nxalice", "/home/nxalice/public_html");
  assert.match(conf, /php_admin_value\[memory_limit\] = 256M/);
  assert.match(conf, /php_admin_value\[request_terminate_timeout\] = 120s/);
  assert.match(conf, /php_admin_value\[open_basedir\] = \/home\/nxalice:\/usr\/share\/php/);
  // /tmp must NOT be on open_basedir (PHP tmp is redirected into the home).
  const basedir = conf.split("\n").find((l) => l.includes("open_basedir")) ?? "";
  assert.ok(!basedir.includes("/tmp"), "open_basedir must not include /tmp");
  // The disable_functions list must be carried into the pool verbatim.
  assert.ok(conf.includes(`disable_functions] = ${phpDisableFunctions()}`));
  assert.match(conf, /upload_tmp_dir\] = \/home\/nxalice\/tmp/);
});

test("GRANT db-name escaping pins a grant to exactly one database", () => {
  // _ and % are LIKE-wildcards in GRANT — must be backslash-escaped.
  assert.equal(escapeGrantDbName("nxalice_wp"), "nxalice\\_wp");
  assert.equal(escapeGrantDbName("a%b"), "a\\%b");
  assert.equal(escapeGrantDbName("a\\b"), "a\\\\b");
  assert.equal(escapeGrantDbName("plain"), "plain");
});

test("buildScopedGrantSql is scoped to the exact db — no wildcard, no *.*", () => {
  const sql = buildScopedGrantSql("nxalice_wp", "nxalice_wp", "pw123");
  // GRANT target has the escaped name and is db-scoped (`.*`), never global.
  assert.ok(sql.includes("GRANT ALL PRIVILEGES ON `nxalice\\_wp`.* TO 'nxalice_wp'@'localhost'"));
  assert.ok(!sql.includes("*.*"), "must never grant on *.*");
  assert.ok(!/\bFILE\b|\bSUPER\b/.test(sql), "no FILE/SUPER");
  // CREATE DATABASE uses the literal (unescaped) name.
  assert.ok(sql.includes("CREATE DATABASE IF NOT EXISTS `nxalice_wp`"));
  assert.ok(sql.includes("FLUSH PRIVILEGES;"));
});

