import { test } from "node:test";
import assert from "node:assert/strict";
import { recommendHostingPlan, planCapacityScore, type HostingPlanSpecs } from "../lib/hosting/recommend.ts";

/* The recommendation is DERIVED from a plan's specs, not hard-coded per plan,
 * so these lock the tiering boundaries a spec ladder should fall into. */

const specs = (o: Partial<HostingPlanSpecs>): HostingPlanSpecs => ({
  diskGB: 1,
  maxSites: 1,
  maxDatabases: 1,
  bandwidthTB: 1,
  ...o,
});

test("a tiny single-site plan reads as starter", () => {
  const r = recommendHostingPlan(specs({ diskGB: 1, maxSites: 1, maxDatabases: 1, bandwidthTB: 0.5 }));
  assert.equal(r.tier, "starter");
  assert.match(r.headline, /one-page|starter/i);
});

test("a ~10 GB blog-grade plan reads as personal", () => {
  const r = recommendHostingPlan(specs({ diskGB: 10, maxSites: 1, maxDatabases: 2, bandwidthTB: 1 }));
  assert.equal(r.tier, "personal");
  assert.match(r.headline, /personal|blog/i);
});

test("a multi-site plan is promoted to business by site count alone", () => {
  const r = recommendHostingPlan(specs({ diskGB: 20, maxSites: 3, maxDatabases: 3, bandwidthTB: 2 }));
  assert.equal(r.tier, "business");
  assert.match(r.detail, /3 sites/);
});

test("a store-grade plan (big bandwidth / disk / many DBs) reads as pro", () => {
  assert.equal(recommendHostingPlan(specs({ diskGB: 100, maxSites: 5, maxDatabases: 10, bandwidthTB: 8 })).tier, "pro");
  // A single strong signal (bandwidth) is enough to reach pro.
  assert.equal(recommendHostingPlan(specs({ diskGB: 20, maxSites: 2, maxDatabases: 3, bandwidthTB: 6 })).tier, "pro");
  // As is a store-grade DB count.
  assert.equal(recommendHostingPlan(specs({ diskGB: 30, maxSites: 2, maxDatabases: 8, bandwidthTB: 3 })).tier, "pro");
});

test("tiering is monotonic in capacity score", () => {
  const ladder: HostingPlanSpecs[] = [
    specs({ diskGB: 1, maxSites: 1, maxDatabases: 1, bandwidthTB: 0.5 }),
    specs({ diskGB: 10, maxSites: 1, maxDatabases: 2, bandwidthTB: 1 }),
    specs({ diskGB: 40, maxSites: 3, maxDatabases: 4, bandwidthTB: 3 }),
    specs({ diskGB: 100, maxSites: 8, maxDatabases: 12, bandwidthTB: 10 }),
  ];
  const scores = ladder.map(planCapacityScore);
  for (let i = 1; i < scores.length; i++) assert.ok(scores[i] > scores[i - 1], `score ${i} not increasing`);
  const tiers = ladder.map((s) => recommendHostingPlan(s).tier);
  assert.deepEqual(tiers, ["starter", "personal", "business", "pro"]);
});

test("degenerate / zero specs never throw and default to starter", () => {
  const r = recommendHostingPlan(specs({ diskGB: 0, maxSites: 0, maxDatabases: 0, bandwidthTB: 0 }));
  assert.equal(r.tier, "starter");
  assert.ok(r.headline.length > 0 && r.detail.length > 0);
});

"use client";

import { useEffect, useRef, useState } from "react";
import {
  orderHostingAccount,
  retryHostingProvision,
  createHostingDatabase,
  listHostingDatabases,
  revealHostingSftpPassword,
  setHostingPhpVersion,
  installWordPress,
  installApp,
  listAppCatalog,
  createHostingBackup,
  listHostingBackups,
  restoreHostingBackup,
  listHostingTasks,
  hostingListFiles,
  hostingMkdir,
  hostingDeleteFile,
  type HostingAccountView,
  type HostingDbView,
  type FsEntryView,
} from "@/lib/actions-hosting";
import { Badge, EmptyState, StatusDot, fmtMoney } from "@/components/ui/primitives";
import { recommendHostingPlan } from "@/lib/hosting/recommend";

type PlanView = {
  id: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
};

export function HostingClient({ plans, accounts }: { plans: PlanView[]; accounts: HostingAccountView[] }) {
  const [domain, setDomain] = useState("");
  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [ok, setOk] = useState("");

  async function order() {
    if (!planId || !domain.trim()) return;
    setBusy(true);
    setError("");
    setOk("");
    try {
      const res = await orderHostingAccount(planId, domain.trim());
      if (res.error) setError(res.error);
      else {
        setOk("Account created — it’s being set up now.");
        setDomain("");
        setTimeout(() => window.location.reload(), 900);
      }
    } catch {
      setError("Something went wrong. Your wallet was not charged — try again.");
    } finally {
      setBusy(false);
    }
  }

  async function retry(id: string) {
    await retryHostingProvision(id);
    window.location.reload();
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-xl font-semibold">Web Hosting</h1>
        <p className="mt-1 text-sm text-slate-400">
          Host your website without managing a server — we run PHP, databases, email and SSL for you. Point your
          domain at us and you’re live.
        </p>
      </div>

      {/* Your accounts (or an empty state prompting the first order). */}
      {accounts.length > 0 ? (
        <div className="space-y-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
          {accounts.map((a) => (
            <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
          ))}
        </div>
      ) : (
        <EmptyState
          title="No hosting accounts yet"
          sub="Pick a plan below, enter your domain, and we’ll set up an isolated hosting account for you in a minute."
        />
      )}

      {/* Order a (new) site. */}
      <div className="card">
        <h2 className="mb-1 font-semibold">{accounts.length ? "Host another site" : "Host a new site"}</h2>
        <p className="mb-3 text-xs text-slate-500">Each site gets its own isolated account, storage quota and databases.</p>
        {error && <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
        {ok && <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{ok}</div>}
        {plans.length === 0 ? (
          <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
        ) : (
          <>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {plans.map((p) => {
                const rec = recommendHostingPlan(p);
                const selected = planId === p.id;
                return (
                  <button
                    key={p.id}
                    type="button"
                    onClick={() => setPlanId(p.id)}
                    className={`flex flex-col rounded-xl border px-4 py-3 text-left transition ${
                      selected ? "border-brand-400 bg-brand-500/10" : "border-white/10 hover:border-white/20"
                    }`}
                  >
                    <div className="flex items-baseline justify-between">
                      <span className="font-medium">{p.name}</span>
                      <span className="text-sm font-semibold">
                        {fmtMoney(p.priceCents)}
                        <span className="text-xs text-slate-500">/mo</span>
                      </span>
                    </div>
                    <p className="mt-1.5 text-xs font-medium text-brand-200">{rec.headline}</p>
                    <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
                      <li>{p.diskGB} GB SSD storage</li>
                      <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
                      <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
                      <li>{p.bandwidthTB} TB bandwidth · free SSL</li>
                    </ul>
                    <p className="mt-2 text-[11px] leading-snug text-slate-500">{rec.detail}</p>
                  </button>
                );
              })}
            </div>
            <div className="mt-4 flex flex-wrap items-end gap-3">
              <div className="min-w-[220px] flex-1">
                <label className="label">Your domain</label>
                <input className="input" placeholder="example.com" value={domain} onChange={(e) => setDomain(e.target.value)} />
              </div>
              <button className="btn-primary" disabled={busy || !planId || !domain.trim()} onClick={order}>
                {busy ? "Creating…" : "Create account"}
              </button>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Charged from your wallet. You don’t need to move your domain yet — you’ll get the exact DNS record to set
              after it’s created.
            </p>
          </>
        )}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- Account --- */

function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
  const [dbs, setDbs] = useState<HostingDbView[]>([]);
  const [dbsLoaded, setDbsLoaded] = useState(false);
  const [dbLabel, setDbLabel] = useState("");
  const [dbBusy, setDbBusy] = useState(false);
  const [dbErr, setDbErr] = useState("");
  const [newDbPassword, setNewDbPassword] = useState<{ name: string; password: string } | null>(null);
  const [sftpPw, setSftpPw] = useState<string | null>(null);
  const [tasks, setTasks] = useState<TaskView[]>([]);

  const active = a.status === "ACTIVE";

  useEffect(() => {
    if (active) listHostingDatabases(a.id).then((d) => { setDbs(d); setDbsLoaded(true); }).catch(() => setDbsLoaded(true));
  }, [a.id, active]);

  async function addDb() {
    if (!dbLabel.trim()) return;
    setDbBusy(true);
    setDbErr("");
    try {
      const res = await createHostingDatabase(a.id, dbLabel.trim());
      if (res.error) setDbErr(res.error);
      else {
        setNewDbPassword({ name: `${a.username}_${dbLabel.trim().toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db"}`, password: res.password ?? "" });
        setDbLabel("");
        listHostingDatabases(a.id).then(setDbs).catch(() => {});
      }
    } finally {
      setDbBusy(false);
    }
  }

  async function reveal() {
    const res = await revealHostingSftpPassword(a.id);
    if (res.password) setSftpPw(res.password);
  }

  const diskGB = Math.round(a.diskQuotaMB / 1024);
  // A freshly provisioned account with nothing set up yet gets the guided panel.
  const isFresh = active && dbsLoaded && dbs.length === 0 && tasks.every((t) => t.status !== "DONE" || t.kind === "PHP_SWITCH");

  return (
    <div className="card space-y-4">
      {/* Overview header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2.5">
          <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="font-medium text-slate-100 hover:underline">
            {a.primaryDomain}
          </a>
          <StatusDot status={a.status} />
          {a.sslActive && <Badge tone="green">HTTPS</Badge>}
        </div>
        <div className="text-xs text-slate-500">
          {a.planName} · PHP {a.phpVersion}
        </div>
      </div>

      {a.status === "FAILED" && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
        </div>
      )}

      {(a.status === "PENDING" || a.status === "PROVISIONING") && (
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-200">
          We’re setting up your account — this usually takes under a minute. This page refreshes as it comes online.
        </div>
      )}

      {/* Quota / usage overview */}
      {active && (
        <div className="grid gap-3 sm:grid-cols-3">
          <QuotaTile label="Storage" primary={`${diskGB} GB SSD`} note="Live usage metering coming soon" />
          <QuotaTile
            label="Websites"
            primary={`1 of ${a.maxSites}`}
            bar={{ used: 1, total: a.maxSites }}
            note={a.maxSites > 1 ? "Extra domains coming soon" : undefined}
          />
          <QuotaTile
            label="Databases"
            primary={a.maxDatabases > 0 ? `${dbs.length} of ${a.maxDatabases}` : "Not on this plan"}
            bar={a.maxDatabases > 0 ? { used: dbs.length, total: a.maxDatabases } : undefined}
          />
        </div>
      )}

      {/* Point-your-domain instructions — the shared-IP A record. */}
      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
        <p className="mb-1 font-medium text-slate-300">Point your domain here</p>
        <p className="text-slate-400">
          Create an <span className="font-mono text-slate-200">A</span> record for{" "}
          <span className="font-mono text-slate-200">{a.primaryDomain}</span> →{" "}
          <span className="font-mono text-brand-200">{a.pointToA}</span>
          {a.pointToCname && (
            <>
              {" "}(or a <span className="font-mono text-slate-200">CNAME</span> to{" "}
              <span className="font-mono text-slate-200">{a.pointToCname}</span>)
            </>
          )}
          . {a.sslActive ? "HTTPS is active." : "HTTPS is issued automatically once it resolves to us."}
        </p>
      </div>

      {/* Getting started — only for a fresh account. */}
      {isFresh && <GettingStarted accountId={a.id} />}

      {/* SFTP access */}
      {active && (
        <div className="flex flex-wrap items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
          <span className="font-medium text-slate-300">SFTP</span>
          <span className="text-slate-400">
            <span className="font-mono text-slate-200">{a.username}</span>@{a.pointToA}
          </span>
          {sftpPw ? (
            <span className="font-mono text-brand-200">{sftpPw}</span>
          ) : (
            <button className="text-xs text-brand-300 hover:underline" onClick={reveal}>show password</button>
          )}
        </div>
      )}

      {/* Quick actions */}
      {active && (
        <div>
          <p className="mb-2 text-sm font-semibold text-slate-300">Quick actions</p>
          <div className="flex flex-wrap items-center gap-x-4 gap-y-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5 text-sm">
            <label className="flex items-center gap-2 text-slate-400">
              PHP version
              <select
                className="input py-1 text-xs"
                defaultValue={a.phpVersion}
                onChange={async (e) => { await setHostingPhpVersion(a.id, e.target.value); }}
              >
                {a.phpVersions.map((v) => (<option key={v} value={v}>{v}</option>))}
              </select>
            </label>
            <span className="hidden h-4 w-px bg-white/10 sm:block" />
            <AppInstaller accountId={a.id} />
            <span className="hidden h-4 w-px bg-white/10 sm:block" />
            <a href="/dashboard/email" className="text-xs font-medium text-brand-300 hover:underline">Set up email →</a>
          </div>
        </div>
      )}

      {/* Task progress + one-time results (WordPress admin login, etc.) */}
      <TaskFeed accountId={a.id} active={active} onTasks={setTasks} />

      {/* File manager */}
      {active && <FileManager accountId={a.id} />}

      {/* Backups */}
      {active && <Backups accountId={a.id} />}

      {/* Databases */}
      {active && a.maxDatabases > 0 && (
        <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
          <p className="mb-1 text-sm font-medium text-slate-300">
            Databases <span className="text-xs text-slate-500">({dbs.length}/{a.maxDatabases})</span>
          </p>
          {dbs.length > 0 && (
            <ul className="mb-2 space-y-0.5 text-xs">
              {dbs.map((d) => (
                <li key={d.id} className="flex items-center gap-2 text-slate-400">
                  <span className="font-mono text-slate-200">{d.name}</span>
                  <span className="text-slate-500">user {d.dbUser}</span>
                  <span className={d.status === "ACTIVE" ? "text-emerald-300" : "text-amber-300"}>{d.status.toLowerCase()}</span>
                </li>
              ))}
            </ul>
          )}
          {newDbPassword && (
            <div className="mb-2 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1.5 text-xs text-emerald-200">
              Created <span className="font-mono">{newDbPassword.name}</span> — password (shown once):{" "}
              <span className="font-mono">{newDbPassword.password}</span>
            </div>
          )}
          {dbs.length < a.maxDatabases ? (
            <div className="flex items-center gap-2">
              <input className="input flex-1 text-xs" placeholder="database name" value={dbLabel} onChange={(e) => setDbLabel(e.target.value)} />
              <button className="btn-secondary text-xs" disabled={dbBusy || !dbLabel.trim()} onClick={addDb}>{dbBusy ? "…" : "Create"}</button>
            </div>
          ) : (
            <p className="text-xs text-slate-500">You’ve used all the databases on your plan.</p>
          )}
          {dbErr && <p className="mt-1 text-xs text-amber-300">{dbErr}</p>}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------- sub-parts --- */

function QuotaTile({
  label,
  primary,
  bar,
  note,
}: {
  label: string;
  primary: string;
  bar?: { used: number; total: number };
  note?: string;
}) {
  const pct = bar && bar.total > 0 ? Math.min(100, Math.round((bar.used / bar.total) * 100)) : null;
  const full = pct !== null && pct >= 100;
  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
      <p className="text-[11px] uppercase tracking-wide text-slate-500">{label}</p>
      <p className="mt-0.5 text-sm font-semibold text-slate-200">{primary}</p>
      {pct !== null && (
        <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div className={`h-full rounded-full ${full ? "bg-amber-400" : "bg-brand-400"}`} style={{ width: `${Math.max(4, pct)}%` }} />
        </div>
      )}
      {note && <p className="mt-1.5 text-[11px] text-slate-500">{note}</p>}
    </div>
  );
}

function GettingStarted({ accountId }: { accountId: string }) {
  const [busy, setBusy] = useState(false);
  return (
    <div className="rounded-lg border border-brand-500/30 bg-brand-500/[0.07] px-3 py-3">
      <div className="mb-1 flex items-center gap-2">
        <Badge tone="brand">getting started</Badge>
        <span className="text-sm font-medium text-slate-200">Your account is ready — here’s how to go live</span>
      </div>
      <ol className="mt-2 space-y-1.5 text-sm text-slate-400">
        <li>
          <span className="font-medium text-slate-300">1. Add your site.</span> Install WordPress in one click, or upload
          your files with the file manager below.
          <button
            className="btn-primary ml-2 px-2.5 py-1 text-xs"
            disabled={busy}
            onClick={async () => { setBusy(true); const r = await installWordPress(accountId); setBusy(false); if (r.error) alert(r.error); else window.location.reload(); }}
          >
            {busy ? "Installing…" : "Install WordPress"}
          </button>
        </li>
        <li>
          <span className="font-medium text-slate-300">2. Point your domain.</span> Set the A record above at your
          registrar so visitors reach your site.
        </li>
        <li>
          <span className="font-medium text-slate-300">3. Get HTTPS.</span> A free SSL certificate is issued automatically
          once your domain resolves to us.
        </li>
      </ol>
    </div>
  );
}

type TaskView = { id: string; kind: string; status: string; result: string | null; error: string | null };

function TaskFeed({ accountId, active, onTasks }: { accountId: string; active: boolean; onTasks?: (t: TaskView[]) => void }) {
  const [tasks, setTasks] = useState<TaskView[]>([]);
  useEffect(() => {
    if (!active) return;
    let stop = false;
    const load = () => listHostingTasks(accountId).then((t) => { if (!stop) { setTasks(t); onTasks?.(t); } }).catch(() => {});
    load();
    const timer = setInterval(load, 5000);
    return () => { stop = true; clearInterval(timer); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [accountId, active]);
  const visible = tasks.filter((t) => t.status !== "DONE" || t.result || t.error);
  if (!visible.length) return null;
  const label: Record<string, string> = { PHP_SWITCH: "PHP version", WORDPRESS_INSTALL: "WordPress install", APP_INSTALL: "App install", BACKUP: "Backup", RESTORE: "Restore" };
  return (
    <div className="space-y-1 text-xs">
      {visible.map((t) => {
        const wp = t.kind === "WORDPRESS_INSTALL" && t.result ? safeJson(t.result) : null;
        const app = t.kind === "APP_INSTALL" && t.result ? safeJson(t.result) : null;
        return (
          <div key={t.id} className={t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}>
            {label[t.kind] ?? t.kind}: {t.status.toLowerCase()}{t.error ? ` — ${t.error}` : ""}
            {wp && (
              <div className="mt-0.5 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1 text-emerald-200">
                WordPress installed — log in at <span className="font-mono">{wp.url}</span> · user <span className="font-mono">{wp.adminUser}</span> · password{" "}
                <span className="font-mono">{wp.adminPassword}</span> (shown once)
              </div>
            )}
            {app && (
              <div className="mt-0.5 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1 text-emerald-200">
                {app.app} deployed — {app.note}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function safeJson(s: string): any {
  try { return JSON.parse(s); } catch { return null; }
}

function Backups({ accountId }: { accountId: string }) {
  const [backups, setBackups] = useState<{ id: string; sizeBytes: number; createdAt: string }[]>([]);
  const [busy, setBusy] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const load = () => listHostingBackups(accountId).then((b) => { setBackups(b); setLoaded(true); }).catch(() => setLoaded(true));
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [accountId]);
  const mb = (b: number) => (b / 1024 / 1024).toFixed(1) + " MB";
  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
      <div className="flex items-center justify-between">
        <p className="text-sm font-medium text-slate-300">Backups <span className="text-xs text-slate-500">({backups.length})</span></p>
        <button
          className="btn-secondary text-xs"
          disabled={busy}
          onClick={async () => { setBusy(true); const r = await createHostingBackup(accountId); if (r.error) alert(r.error); setBusy(false); setTimeout(load, 1500); }}
        >
          {busy ? "…" : "Back up now"}
        </button>
      </div>
      {loaded && backups.length === 0 && (
        <p className="mt-1.5 text-xs text-slate-500">No backups yet. Run one before big changes — we keep the latest 5.</p>
      )}
      {backups.length > 0 && (
        <ul className="mt-2 space-y-0.5 text-xs">
          {backups.map((b) => (
            <li key={b.id} className="flex items-center justify-between text-slate-400">
              <span>{new Date(b.createdAt).toLocaleString()} · {mb(b.sizeBytes)}</span>
              <button
                className="text-brand-300 hover:underline"
                onClick={async () => { if (confirm("Restore this backup? It overwrites current files and databases.")) { const r = await restoreHostingBackup(accountId, b.id); if (r.error) alert(r.error); } }}
              >
                Restore
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function AppInstaller({ accountId }: { accountId: string }) {
  const [apps, setApps] = useState<{ slug: string; name: string; needsDb: boolean }[]>([]);
  const [busy, setBusy] = useState(false);
  useEffect(() => { listAppCatalog().then(setApps).catch(() => {}); }, []);
  async function pick(value: string) {
    if (!value) return;
    setBusy(true);
    const r = value === "wordpress" ? await installWordPress(accountId) : await installApp(accountId, value);
    setBusy(false);
    if (r.error) alert(r.error); else window.location.reload();
  }
  return (
    <label className="flex items-center gap-1.5 text-slate-400">
      Install app
      <select className="input py-1 text-xs" defaultValue="" disabled={busy} onChange={(e) => pick(e.target.value)}>
        <option value="">{busy ? "Installing…" : "choose…"}</option>
        <option value="wordpress">WordPress (auto)</option>
        {apps.map((ap) => (<option key={ap.slug} value={ap.slug}>{ap.name}</option>))}
      </select>
    </label>
  );
}

function FileManager({ accountId }: { accountId: string }) {
  const [open, setOpen] = useState(false);
  const [path, setPath] = useState("public_html");
  const [entries, setEntries] = useState<FsEntryView[]>([]);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  async function load(p: string) {
    setBusy(true); setErr("");
    const r = await hostingListFiles(accountId, p);
    setBusy(false); setLoaded(true);
    if (r.error) setErr(r.error); else { setEntries(r.entries ?? []); setPath(r.path ?? p); }
  }
  useEffect(() => { if (open) load(path); /* eslint-disable-next-line */ }, [open]);

  const parent = () => { const parts = path.split("/").filter(Boolean); parts.pop(); load(parts.join("/") || "public_html"); };
  async function upload(files: FileList | null) {
    if (!files?.length) return;
    setBusy(true);
    for (const f of Array.from(files)) {
      const fd = new FormData(); fd.append("file", f);
      await fetch(`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(path)}`, { method: "POST", body: fd }).catch(() => {});
    }
    if (fileRef.current) fileRef.current.value = "";
    load(path);
  }

  if (!open) return <button className="text-xs font-medium text-brand-300 hover:underline" onClick={() => setOpen(true)}>Open file manager</button>;
  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
      <div className="mb-2 flex items-center justify-between">
        <span className="font-mono text-xs text-slate-400">/{path}</span>
        <div className="flex items-center gap-2 text-xs">
          <button className="text-brand-300 hover:underline" onClick={() => fileRef.current?.click()}>Upload</button>
          <input ref={fileRef} type="file" multiple className="hidden" onChange={(e) => upload(e.target.files)} />
          <button className="text-slate-400 hover:underline" onClick={async () => { const n = prompt("New folder name"); if (n) { const r = await hostingMkdir(accountId, path, n); if (r.error) alert(r.error); else load(path); } }}>New folder</button>
          <button className="text-slate-500 hover:underline" onClick={() => setOpen(false)}>close</button>
        </div>
      </div>
      {err && <p className="text-xs text-amber-300">{err}</p>}
      {busy && <p className="text-xs text-slate-500">Loading…</p>}
      {loaded && !busy && !err && entries.length === 0 && path === "public_html" && (
        <p className="px-1 py-2 text-xs text-slate-500">This folder is empty. Upload your site files here, or install an app above.</p>
      )}
      <ul className="max-h-56 overflow-auto text-xs">
        {path !== "public_html" && path !== "" && (
          <li><button className="text-slate-400 hover:underline" onClick={parent}>⬆ ..</button></li>
        )}
        {entries.map((e) => (
          <li key={e.name} className="flex items-center justify-between py-0.5">
            {e.isDir ? (
              <button className="text-brand-200 hover:underline" onClick={() => load(`${path}/${e.name}`)}>📁 {e.name}</button>
            ) : (
              <a className="text-slate-300 hover:underline" href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${e.name}`)}`}>📄 {e.name}</a>
            )}
            <span className="flex items-center gap-2 text-slate-500">
              {!e.isDir && <span>{(e.size / 1024).toFixed(0)} KB</span>}
              <button className="text-red-400 hover:underline" onClick={async () => { if (confirm(`Delete ${e.name}?`)) { const r = await hostingDeleteFile(accountId, `${path}/${e.name}`, e.isDir); if (r.error) alert(r.error); else load(path); } }}>del</button>
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

